        for entry in session_log:
            if entry.get('server') and manifest.get(entry['server'], {}).get('trust_level') in privileged_levels:
                output = entry.get('output')
                if output:
                    def extract_strings(obj):
                        if isinstance(obj, str) and len(obj) >= 4:
                            tainted_strings.add(obj)
                        elif isinstance(obj, dict):
                            for v in obj.values():
